+	tlfCounts map[tlf.ID]int
+	numBlocks int
+	// Track the aggregate size of blocks in the cache per TLF and overall.
+	tlfSizes  map[tlf.ID]uint64
+	currBytes uint64
+	// This protects the disk caches from being shutdown while they're being
+	// accessed.
