private Prepared parseAlterTable() {
    boolean ifTableExists = readIfExists(false);
    String tableName = readIdentifierWithSchema();
    Schema schema = getSchema();

    // ...
    } else if (readIf("DROP")) {
        // ...
        } else {
            readIf("COLUMN");
            boolean ifExists = readIfExists(false);
            AlterTableAlterColumn command = new AlterTableAlterColumn(
                    session, schema);
            command.setType(CommandInterface.ALTER_TABLE_DROP_COLUMN);
            ArrayList<Column> columnsToRemove = New.arrayList();
            Table table = tableIfTableExists(schema, tableName, ifTableExists);
            readIf("("); // For Oracle compatibility - open bracket required
            do {
                String columnName = readColumnIdentifier();
                if (table == null) {
                    return new NoOperation(session);
                }
                if (ifExists && !table.doesColumnExist(columnName)) {
                    return new NoOperation(session);
                }
                Column column = table.getColumn(columnName);
                columnsToRemove.add(column);
            } while (readIf(","));
            if (openingBracketDetected) {
                read(")"); // For Oracle compatibility - close bracket
            }
            command.setTableName(tableName);
            command.setIfTableExists(ifTableExists);
            command.setColumnsToRemove(columnsToRemove);
            return command;
        }
    }
}
