+   *
+   * @return the pipe's capacity.
+   */
+  public int getCapacity() {
+    return capacity;
+  }
+
+  @Override
+  public boolean hasRemainingCapacity() {
+    return queue.remainingCapacity() > 0 && isOpen();
+  }
+
+  @Override
