+    closed.set(true);
+  }
+
+  @Override
+  public void abort() {
+    aborted.set(true);
+  }
+
+  @Override
+  public boolean hasMore() {
+    if (aborted.get()) {
+      return false;
+    }
+    return !closed.get() || !queue.isEmpty();
+  }
+
+  @Override
+  public T get() {
+    try {
+      while (hasMore()) {
+        final T value = queue.poll(1, TimeUnit.SECONDS);
+        if (value != null) {
+          return value;
+        }
+      }
+    } catch (final InterruptedException e) {
+      LOG.trace("Interrupted while waiting for next item", e);
+    }
+    return null;
+  }
+
+  @Override
+  public T poll() {
+    return queue.poll();
+  }
