+        }
+
+        public Expression Expression { get; }
+
+        protected internal override void AcceptVisitor(IExpressionVisitor visitor)
+        {
+            EnsureArg.IsNotNull(visitor, nameof(visitor));
+            visitor.Visit(this);
+        }
+    }
