+    CDRMessage::readUInt32(msg, &data.ts.fraction);
+    CDRMessage::readUInt64(msg, &data.seq.sequence);
+    CDRMessage::readUInt64(msg, &data.seq.bytes);
+    CDRMessage::readUInt16(msg, &data.seq.bytes_high);
