+
+        return $escargot;
+    }
+
+    private function createDefaultHttpClient(): HttpClientInterface
+    {
+        return HttpClient::create($this->getDefaultHttpClientOptions());
+    }
+
+    private function registerDefaultSubscribers(Escargot $escargot): void
+    {
